"""Generate mathematical FM tables. No recorded sound is stored in these ROMs."""
from pathlib import Path
import math

ROOT = Path(__file__).resolve().parents[1]
FS = 50_000_000 / 1040


def generate():
    lines = [
        '// Generated by ../tools/generate_tables.py; mathematical sine only.',
        'module fm_sine_rom(input wire clk, input wire [9:0] address_a, address_b,',
        '    output reg signed [15:0] value_a, value_b);',
        'reg signed [15:0] memory [0:1023];',
        'initial begin',
    ]
    for i in range(1024):
        value = round(32767 * math.sin(2 * math.pi * i / 1024))
        lines.append(f"    memory[{i}] = 16'h{value & 65535:04X};")
    lines += ['end', 'always @(posedge clk) begin',
              '    value_a <= memory[address_a];',
              '    value_b <= memory[address_b];', 'end', 'endmodule', '']
    (ROOT / 'src/fm_sine_rom.v').write_text('\n'.join(lines), encoding='utf-8')
    lines = ['// Generated by ../tools/generate_tables.py; Fs=50 MHz/1040.',
             'module fm_note_table(input wire [6:0] note, output reg [31:0] phase_step);',
             'always @* begin', '    case (note)']
    for note in range(36, 85):
        frequency = 440 * 2 ** ((note - 69) / 12)
        step = round(frequency / FS * 2 ** 32)
        lines.append(f"        7'd{note}: phase_step = 32'h{step:08X}; // {frequency:.9f} Hz")
    lines += ["        default: phase_step = 32'd0;", '    endcase', 'end', 'endmodule', '']
    (ROOT / 'src/fm_note_table.v').write_text('\n'.join(lines), encoding='utf-8')
    print('FM mathematical tables generated')


if __name__ == '__main__':
    generate()
